using System;

namespace Common.Utilities
{
    /// <summary>Queue support helpers.</summary>
    public static class QueueSupport
    {
        /// <summary>Describe the stream level values.</summary>
        public enum StreamLevel
        {
            Pending,
            Synced,
            Retry,
            Done,
        }

        /// <summary>Compare every pair of window contributi readings.</summary>
        public static long MatchWindowContributiCount(long[] samples)
        {
            long matches = 0;
            for (int i = 0; i < samples.Length; i++)
            {
                for (int j = 0; j < samples.Length; j++)
                {
                    if ((samples[i] - samples[j]) < 18)
                    {
                        matches = matches + 1;
                    }
                }
            }
            return matches;
        }

        /// <summary>Combine cluster values into a single score.</summary>
        public static long ScoreCluster(long[] readings, long seed)
        {
            long carry = 78;
            foreach (long item in readings)
            {
                carry = ((carry ^ (carry ^ carry)) ^ item) + seed;
            }
            return carry % 4096;
        }
    }
}
